// ============================================================================
// Root Store
// ============================================================================

export class RootStore {
  user: UserStore
  account: AccountStore
  transaction: TransactionStore
  budget: BudgetStore
  goal: GoalStore
  portfolio: PortfolioStore
  recommendation: RecommendationStore

  constructor() {
    this.user = new UserStore()
    this.account = new AccountStore()
    this.transaction = new TransactionStore()
    this.budget = new BudgetStore()
    this.goal = new GoalStore()
    this.portfolio = new PortfolioStore()
    this.recommendation = new RecommendationStore()
    makeAutoObservable(this)
  }

  /** Clear all stores */
  clearAll() {
    this.user.clear()
    this.account.clear()
    this.transaction.clear()
    this.budget.clear()
    this.goal.clear()
    this.portfolio.clear()
    this.recommendation.clear()
  }
}

// ============================================================================
// Factory & Singleton
// ============================================================================

let rootStore: RootStore | null = null

/**
 * Get or create the root store singleton
 */
export function getStore(): RootStore {
  if (!rootStore) {
    rootStore = new RootStore()
  }
  return rootStore
}

/**
 * Create a new root store (for testing or SSR)
 */
export function createStore(): RootStore {
  return new RootStore()
}

/**
 * Reset the singleton store
 */
export function resetStore(): void {
  rootStore = null
}
